"""Fetch visitor counts from GoatCounter's public visitor-counter endpoint and write _data/visitors.yml.

Runs daily from .github/workflows/visitors.yml, or by hand:  python .github/scripts/fetch_visitors.py

The site renders these numbers statically (home page tiles, footer, paper pages), so they show
even for readers whose browsers block third-party requests; the page scripts then refresh them
live when they can. Standard library only.
"""
import glob, json, os, re, datetime, time
import urllib.request, urllib.parse, urllib.error

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
OUT = os.path.join(ROOT, "_data", "visitors.yml")
BASE = "https://albertojaspe.goatcounter.com/counter/"
HEADERS = {"User-Agent": "albertojaspe.net visitor stats updater (github action)"}


def count(path, query=""):
    url = BASE + ("TOTAL" if path == "TOTAL" else urllib.parse.quote(path, safe="")) + ".json" + query
    try:
        req = urllib.request.Request(url, headers=HEADERS)
        with urllib.request.urlopen(req, timeout=30) as r:
            data = json.loads(r.read().decode("utf-8"))
        digits = re.sub(r"[^0-9]", "", str(data.get("count", "0")))
        return int(digits) if digits else 0
    except urllib.error.HTTPError as e:
        if e.code == 404:        # path never visited
            return 0
        raise


# explicit dates: the "week"/"month" shorthands are cached for hours and were stale after the import
def since(days):
    return "?start=" + (datetime.date.today() - datetime.timedelta(days=days)).isoformat()
week = count("TOTAL", since(7))
month = count("TOTAL", since(30))
total = count("TOTAL", "?start=2000-01-01")

# Daily counts for the chart on the home page: the last DAYS complete days, one request per day.
# The counter endpoint takes "end" as exclusive, so start=D&end=D+1 is the count of day D.
# Days already in the file are kept (only the last two are refetched), so a normal run adds two requests.
DAYS = 30
today = datetime.date.today()
old_daily = {}
if os.path.exists(OUT):
    for m in re.finditer(r'^  - \{ date: "(\d{4}-\d{2}-\d{2})", count: (\d+) \}$', open(OUT, encoding="utf-8").read(), re.M):
        old_daily[m.group(1)] = int(m.group(2))
daily = []
for i in range(DAYS, 0, -1):
    day = today - datetime.timedelta(days=i)
    key = day.isoformat()
    if key in old_daily and i > 2:
        n = old_daily[key]
    else:
        n = count("TOTAL", "?start=%s&end=%s" % (key, (day + datetime.timedelta(days=1)).isoformat()))
        time.sleep(0.3)
    daily.append((key, n))

pages = {}
for path in sorted(glob.glob(os.path.join(ROOT, "_publications", "*.md"))):
    fm = open(path, encoding="utf-8").read()
    if re.search(r"^published:\s*false", fm, re.M):
        continue
    url = "/publications/" + os.path.basename(path)[:-3] + ".html"
    n = count(url)
    if n > 0:
        pages[url] = n
    time.sleep(0.3)
for url in ("/", "/research.html", "/publications/", "/news/", "/notes.html"):
    n = count(url)
    if n > 0:
        pages[url] = n
    time.sleep(0.3)

lines = [
    "# Generated by .github/scripts/fetch_visitors.py (daily GitHub Action). Do not edit by hand.",
    "updated: %s" % datetime.date.today().isoformat(),
    "week: %d" % week,
    "month: %d" % month,
    "total: %d" % total,
    "daily:",
]
for key, n in daily:
    lines.append('  - { date: "%s", count: %d }' % (key, n))
lines.append("pages:")
for url in sorted(pages):
    lines.append('  "%s": %d' % (url, pages[url]))
os.makedirs(os.path.dirname(OUT), exist_ok=True)
with open(OUT, "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(lines) + "\n")
print("week=%d month=%d total=%d pages=%d" % (week, month, total, len(pages)))
